import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import * as atom from "../html/atom/index.ts";
import * as html from "../html/index.ts";
import * as bytes from "../runtime/bytes.ts";
import * as conv from "../runtime/conv.ts";
import * as util from "./html.ts";
import * as utilIndex from "./index.ts";

// Vectors are generated by ts/tools/gen-util-vectors (subcommand "html") from Go's real
// util/html.go (-tags javascript). Each document is the HTML of a corpus entry; ParseHTML is
// run on it and every element of the result is a vector target, found by its path (the child
// indexes from the returned node, "" for the node itself).
//
// Encoding. A helper result that is the zero value (null, "", false, an empty list) is left out
// of an element record, so a missing field means the zero value. A string is stored verbatim,
// or as {sha256, len} of its UTF-8 bytes when it is longer than 200 bytes.
//
// Every element is checked against every helper, so the test also asserts the zero values.

interface Hashed {
  sha256: string;
  len: number;
}
type SV = string | Hashed;

interface TMRec {
  tdwc: SV;
  td: SV;
  imd: SV;
  ahref: SV;
  atitle: SV;
  imath: SV;
  bid: SV;
  bsub: SV;
  fa: SV;
  fo: SV;
  tx: SV;
}

interface MutRec {
  op: string;
  name?: string;
  val?: string;
  html: SV;
}

interface ElemRec {
  p: string;
  html: SV;
  attr?: Record<string, string>;
  ex?: string[];
  custom?: Record<string, string>;
  prefix?: Record<string, Record<string, string>>;
  cbc?: { q: number; r: string }[];
  cbt?: { q: number; p: string[] }[];
  exq?: number[];
  tms?: boolean;
  text?: SV;
  tm?: TMRec;
  mut?: MutRec[];
}

interface DocRec {
  kind: string;
  src: string;
  root: SV | null;
  elems: ElemRec[];
}

interface ClassQuery {
  atom: string;
  classes: string[] | null;
}

interface Vectors {
  goVersion: string;
  attrNames: string[];
  prefixes: string[];
  classQueries: ClassQuery[];
  atomNames: string[];
  existQueries: string[][];
  docs: DocRec[];
}

const vectors: Vectors = JSON.parse(readFileSync(new URL("./testdata/util_html_vectors.json", import.meta.url), "utf8"));

const sha256 = (s: string): string => createHash("sha256").update(s, "utf8").digest("hex");

// check asserts that actual is the recorded value: a string stored verbatim, or a hash and length.
function check(actual: string, expected: SV | undefined, where: string): void {
  const want: SV = expected ?? "";
  if (typeof want === "string") {
    assert.equal(actual, want, where);
    return;
  }
  assert.equal(Buffer.byteLength(actual, "utf8"), want.len, `${where}: byte length`);
  assert.equal(sha256(actual), want.sha256, `${where}: sha256`);
}

// renderNode is html.Render of one node, as the vectors record it.
function renderNode(n: html.Node): string {
  const buf = new bytes.Buffer();
  assert.equal(html.Render(buf, n), null, "Render");
  return buf.String();
}

const atomOf = (name: string): atom.Atom => atom.Lookup(conv.BytesFromString(name));

// pathsOf gives the path of every node of a tree, in the form the generator writes.
function pathsOf(root: html.Node): Map<html.Node, string> {
  const paths = new Map<html.Node, string>();
  const walk = (n: html.Node, path: string): void => {
    paths.set(n, path);
    let i = 0;
    for (let c = n.FirstChild; c !== null; c = c.NextSibling) {
      walk(c, path === "" ? String(i) : `${path}/${i}`);
      i++;
    }
  };
  walk(root, "");
  return paths;
}

// findByPath returns the node at a path of child indexes from root.
function findByPath(root: html.Node, path: string): html.Node {
  let n: html.Node = root;
  if (path === "") {
    return n;
  }
  for (const part of path.split("/")) {
    let c: html.Node | null = n.FirstChild;
    for (let k = Number(part); k > 0; k--) {
      c = c!.NextSibling;
    }
    n = c!;
  }
  return n;
}

const mapOrNull = (m: Map<string, string> | null): Record<string, string> | null =>
  m === null ? null : Object.fromEntries(m);

interface Prepared {
  doc: DocRec;
  root: html.Node | null;
  paths: Map<html.Node, string>;
}

// prepare parses every document with ParseHTML and checks the tree against the element list.
const prepared: Prepared[] = vectors.docs.map((doc, di) => {
  const where = `doc#${di} ${JSON.stringify(doc.src).slice(0, 80)}`;
  const root = util.ParseHTML(doc.src);
  if (doc.root === null) {
    assert.equal(root, null, `${where}: ParseHTML returns nil`);
    assert.equal(doc.elems.length, 0, where);
    return { doc, root, paths: new Map() };
  }
  assert.notEqual(root, null, `${where}: ParseHTML returns a node`);
  const paths = pathsOf(root!);
  const elements = [...paths.keys()].filter((n) => n.Type === html.ElementNode);
  assert.equal(doc.elems.length, elements.length, `${where}: element count`);
  return { doc, root, paths };
});

// eachElement runs body on every element of every document, with the node found by path.
function eachElement(
  body: (n: html.Node, e: ElemRec, p: Prepared, where: string) => void,
): void {
  for (const [di, p] of prepared.entries()) {
    if (p.root === null) {
      continue;
    }
    for (const [ei, e] of p.doc.elems.entries()) {
      const where = `doc#${di} elem#${ei} path=${JSON.stringify(e.p)} ${JSON.stringify(p.doc.src).slice(0, 80)}`;
      const n = findByPath(p.root, e.p);
      assert.equal(n.Type, html.ElementNode, `${where}: element`);
      body(n, e, p, where);
    }
  }
}

test("vector corpus size", () => {
  const docs = vectors.docs.length;
  const elems = vectors.docs.reduce((s, d) => s + d.elems.length, 0);
  assert.ok(docs >= 150, `documents: ${docs}`);
  assert.ok(elems >= 1000, `elements: ${elems}`);
  assert.ok(vectors.docs.some((d) => d.root === null), "a document whose ParseHTML result is nil");
  assert.ok(vectors.attrNames.length >= 20, "attribute names");
});

test("util index re-exports the ported files", () => {
  assert.equal(utilIndex.ParseHTML, util.ParseHTML);
  assert.equal(utilIndex.DomAttrValue, util.DomAttrValue);
  assert.equal(typeof utilIndex.IsDocIAL, "function");
  assert.equal(typeof utilIndex.PathEscape, "function");
  assert.equal(typeof utilIndex.WordCount, "function");
  assert.equal(typeof utilIndex.StrToBytes, "function");
  assert.equal(typeof utilIndex.RecoverPanic, "function");
});

test("ParseHTML matches Go (rendered result of every document)", () => {
  for (const [di, p] of prepared.entries()) {
    const where = `doc#${di}`;
    if (p.doc.root === null) {
      assert.equal(p.root, null, where);
      continue;
    }
    check(renderNode(p.root!), p.doc.root, where);
  }
});

test("DomHTML matches Go (every element)", () => {
  eachElement((n, e, _p, where) => {
    check(conv.StringFromBytes(util.DomHTML(n)), e.html, where);
  });
});

test("DomAttrValue and ExistDomAttr match Go for every attribute name", () => {
  eachElement((n, e, _p, where) => {
    for (const name of vectors.attrNames) {
      const w = `${where} attr=${name}`;
      assert.equal(util.DomAttrValue(n, name), e.attr?.[name] ?? "", w);
      assert.equal(util.ExistDomAttr(n, name), e.ex?.includes(name) ?? false, w);
    }
  });
});

test("DomCustomAttrs matches Go", () => {
  eachElement((n, e, _p, where) => {
    assert.deepEqual(mapOrNull(util.DomCustomAttrs(n)), e.custom ?? null, where);
  });
});

test("DomAttrValuesWithPrefix matches Go for every prefix", () => {
  eachElement((n, e, _p, where) => {
    for (const pfx of vectors.prefixes) {
      assert.deepEqual(mapOrNull(util.DomAttrValuesWithPrefix(n, pfx)), e.prefix?.[pfx] ?? null, `${where} prefix=${pfx}`);
    }
  });
});

test("DomChildByTypeAndClass matches Go for every query", () => {
  eachElement((n, e, p, where) => {
    vectors.classQueries.forEach((q, qi) => {
      const got = util.DomChildByTypeAndClass(n, atomOf(q.atom), ...(q.classes ?? []));
      assert.ok(got === null || p.paths.has(got), `${where} query=${qi}: result is in the tree`);
      const gotPath = got === null ? null : (p.paths.get(got) ?? null);
      const want = e.cbc?.find((x) => x.q === qi)?.r ?? null;
      assert.equal(gotPath, want, `${where} query=${qi}`);
    });
  });
});

test("DomChildrenByType matches Go for every atom", () => {
  eachElement((n, e, p, where) => {
    vectors.atomNames.forEach((name, ai) => {
      const got = util.DomChildrenByType(n, atomOf(name)).map((c) => p.paths.get(c));
      const want = e.cbt?.find((x) => x.q === ai)?.p ?? [];
      assert.deepEqual(got, want, `${where} atom=${name}`);
    });
  });
});

test("DomExistChildByType matches Go for every atom set", () => {
  eachElement((n, e, _p, where) => {
    vectors.existQueries.forEach((set, qi) => {
      const got = util.DomExistChildByType(n, ...set.map(atomOf));
      assert.equal(got, e.exq?.includes(qi) ?? false, `${where} set=${JSON.stringify(set)}`);
    });
  });
});

test("IsTempMarkSpan matches Go", () => {
  eachElement((n, e, _p, where) => {
    assert.equal(util.IsTempMarkSpan(n), e.tms ?? false, where);
  });
});

test("DomText matches Go", () => {
  eachElement((n, e, _p, where) => {
    check(util.DomText(n), e.text, where);
  });
});

test("GetTextMark*Data, GetFormula and DomTexhtml match Go on span and img", () => {
  let checked = 0;
  eachElement((n, e, _p, where) => {
    if (n.DataAtom !== atom.Span && n.DataAtom !== atom.Img) {
      assert.equal(e.tm, undefined, `${where}: no text mark record`);
      return;
    }
    const tm = e.tm;
    assert.notEqual(tm, undefined, `${where}: text mark record`);
    const t = tm!;
    check(util.GetTextMarkTextDataWithoutEscapeQuote(n), t.tdwc, `${where} tdwc`);
    check(util.GetTextMarkTextData(n), t.td, `${where} td`);
    check(util.GetTextMarkInlineMemoData(n), t.imd, `${where} imd`);
    const [href, title] = util.GetTextMarkAData(n);
    check(href, t.ahref, `${where} ahref`);
    check(title, t.atitle, `${where} atitle`);
    check(util.GetTextMarkInlineMathData(n), t.imath, `${where} imath`);
    const [id, subtype] = util.GetTextMarkBlockRefData(n);
    check(id, t.bid, `${where} bid`);
    check(subtype, t.bsub, `${where} bsub`);
    check(util.GetTextMarkFileAnnotationRefData(n), t.fa, `${where} fa`);
    check(util.GetFormula(n), t.fo, `${where} fo`);
    check(util.DomTexhtml(n), t.tx, `${where} tx`);
    checked++;
  });
  assert.ok(checked > 0, "span and img elements in the corpus");
});

test("SetDomAttrValue and RemoveDomAttrs (RemoveDomAttr) match Go on a fresh tree", () => {
  let checked = 0;
  for (const p of prepared) {
    if (p.root === null) {
      continue;
    }
    for (const [ei, e] of p.doc.elems.entries()) {
      const where = `${p.doc.kind} elem#${ei} path=${JSON.stringify(e.p)}`;
      const original = findByPath(p.root, e.p);
      const firstKey = original.Attr.length > 0 ? original.Attr[0].Key : null;
      const want = ["setNew", "removeAll", ...(firstKey === null ? [] : ["setFirst", "removeFirst"])];
      assert.deepEqual((e.mut ?? []).map((m) => m.op), want, where);
      for (const m of e.mut ?? []) {
        const fresh = util.ParseHTML(p.doc.src);
        assert.notEqual(fresh, null, where);
        const t = findByPath(fresh!, e.p);
        switch (m.op) {
          case "setNew":
            util.SetDomAttrValue(t, m.name!, m.val!);
            break;
          case "removeAll":
            util.RemoveDomAttrs(t);
            break;
          case "setFirst":
            assert.equal(m.name, firstKey, where);
            util.SetDomAttrValue(t, m.name!, m.val!);
            break;
          case "removeFirst":
            assert.equal(m.name, firstKey, where);
            util.RemoveDomAttr(t, m.name!);
            break;
          default:
            assert.fail(`unknown op ${m.op}`);
        }
        check(renderNode(t), m.html, `${where} op=${m.op}`);
        checked++;
      }
    }
  }
  assert.ok(checked > 0, "mutation vectors");
});
